-- Retired sign-in identities retain their ledger-backed profiles. The
-- certification predicate intentionally has no registration for these peers.
CREATE TABLE auth.users(id uuid PRIMARY KEY, deleted_at timestamptz);
SELECT id,'10000000-0000-4000-8000-000000000001' FROM social_conversations
WHERE id IN ('20000000-0000-4000-8000-000000000010','20000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000012','20000000-0000-4000-8000-000000000020');
SELECT c.id,c.id,p.user_id,false,c.last_message_at FROM social_conversations c
JOIN social_conversation_participants p ON p.conversation_id=c.id
WHERE c.id IN ('20000000-0000-4000-8000-000000000010','20000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000012','20000000-0000-4000-8000-000000000020')
AND p.user_id<>'10000000-0000-4000-8000-000000000001';
